#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: pilot of issue #10 (docs/pilot/README.md). Run from the repo root.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=12

[[ -f package.json && -f docs/pilot/config.template.json ]] || { echo "Rode da raiz do checkout do my-software-factory."; exit 1; }
PILOT_DIR=".pilot"
mkdir -p "$PILOT_DIR"
ENV_FILE="$PILOT_DIR/pilot.env"     # git-ignored: holds the Jira token and the choices of this machine
CONFIG="$PILOT_DIR/config.json"
LOCAL="$PILOT_DIR/local.json"
TEMPLATE="docs/pilot/config.template.json"
IMAGE="msf-docker-runner:local"
JIRA_BASE="https://bancojohndeere.atlassian.net"
ACCOUNT_PESSOAL="Sanmoo"
ACCOUNT_TRABALHO="samuel-santos_bjd"


# ask_or KEY "Prompt" DEFAULT: like ask, but offers DEFAULT on the first run.
ask_or() {
  local key="$1" prompt="$2" default="$3" input current
  current=$(_existing "$key" || true)
  [[ -z "$current" ]] && current="$default"
  printf '  %s%s%s %s[Enter = %s]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$current" "$RESET"
  read -r input || true
  [[ -z "$input" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# no_spaces VALUE: the env file is sourced by the run helper, so values stay free of whitespace.
no_spaces() { [[ "$1" != *[[:space:]]* ]]; }

# all_projects: instance|name|repository|adapter|account|jiraKey — straight from the template.
all_projects() {
  node -e '
    const c = JSON.parse(require("fs").readFileSync(process.argv[1], "utf8"));
    for (const i of c.instances) for (const p of i.projects)
      console.log([i.name, p.name, p.repository, p.adapter, p.githubAccount, p.jira?.projectKey ?? ""].join("|"));
  ' "$TEMPLATE"
}

# gh_as ACCOUNT args...: runs gh with that account's token, never switching the active account.
gh_as() { local account="$1"; shift; GH_TOKEN=$(gh auth token --user "$account") gh "$@"; }

# ensure_label ACCOUNT REPO NAME COLOR DESCRIPTION: creates the label only when it does not exist yet.
ensure_label() {
  if gh_as "$1" api "repos/$2/labels/$3" --silent >/dev/null 2>&1; then say "ok   $2: $3 já existe"
  elif gh_as "$1" label create "$3" -R "$2" --color "$4" --description "$5" >/dev/null; then say "ok   $2: $3 criada"
  else warn "$2: não consegui criar a label $3"; SKIPPED+=("label $3 em $2"); fi
}

# jira_get PATH: authenticated GET on Jira Cloud; credentials go through stdin, not the command line.
jira_get() {
  printf 'user = "%s:%s"\n' "$JIRA_USERNAME" "$JIRA_API_TOKEN" |
    curl -fsS -K - -H 'Accept: application/json' "$JIRA_BASE$1"
}

banner "Piloto da factory (#10): instâncias trabalho e pessoal"

# ── 1 ─────────────────────────────────────────────────────────────────────
stage "Pré-requisitos da máquina"
say "Verifico Node, Docker, Pi e as duas contas do gh. Nada é alterado."
missing=0
for tool in node git gh docker pi curl; do
  if command -v "$tool" >/dev/null 2>&1; then say "ok   $tool"; else warn "falta $tool no PATH"; missing=1; fi
done
docker info >/dev/null 2>&1 && say "ok   Docker responde" || { warn "Docker não responde (inicie o colima/Docker Desktop)"; missing=1; }
for account in "$ACCOUNT_PESSOAL" "$ACCOUNT_TRABALHO"; do
  if gh auth token --user "$account" >/dev/null 2>&1; then say "ok   gh tem token da conta $account"
  else warn "gh sem a conta $account: rode 'gh auth login' e entre com ela"; missing=1; fi
done
if (( missing )); then
  warn "Corrija o que falhou acima e rode o wizard de novo (ele lembra o que já salvou)."; exit 1
fi
if [[ ! -d node_modules ]]; then step "Instalando dependências (npm ci --ignore-scripts)"; npm ci --ignore-scripts; fi

# ── 2 ─────────────────────────────────────────────────────────────────────
stage "Imagem Docker do runner"
say "A imagem inclui o Pi e o gh (o container abre o PR com o GH_TOKEN da conta do projeto)."
if docker image inspect "$IMAGE" >/dev/null 2>&1 && docker run --rm --entrypoint gh "$IMAGE" --version >/dev/null 2>&1; then
  say "ok   $IMAGE já existe e tem o gh"
else
  warn "$IMAGE não existe ou é antiga (sem gh)."
  if confirm "Construir agora? (alguns minutos; o apt pode falhar de forma transitória: rode de novo)"; then
    docker build --build-arg AGENT_UID="$(id -u)" --build-arg AGENT_GID="$(id -g)" -t "$IMAGE" src/runtime/docker-image
  else
    SKIPPED+=("imagem $IMAGE (docker build --build-arg AGENT_UID=\$(id -u) --build-arg AGENT_GID=\$(id -g) -t $IMAGE src/runtime/docker-image)")
  fi
fi

# ── 3 ─────────────────────────────────────────────────────────────────────
stage "Jira: token de API e conta do operador"
say "A factory lê e escreve no Jira com o seu token (só leitura/claim/comentário/transição)."
open_url "https://id.atlassian.com/manage-profile/security/api-tokens"
step "Clique em 'Create API token', nomeie 'msf-pilot', crie e copie o token."
write_env JIRA_URL "$JIRA_BASE"
attempts=0
while true; do
  attempts=$((attempts + 1))
  (( attempts <= 3 )) || { warn "três tentativas sem sucesso; confira o token e rode o wizard de novo"; exit 1; }
  ask JIRA_USERNAME "E-mail da sua conta Atlassian:"
  ask_secret JIRA_API_TOKEN "Cole o token:"
  if me=$(jira_get "/rest/api/3/myself" 2>/dev/null); then break; fi
  warn "o Jira recusou essas credenciais; confira e tente de novo"
done
write_env JIRA_USERNAME "$JIRA_USERNAME"
write_env JIRA_API_TOKEN "$JIRA_API_TOKEN"
JIRA_OPERATOR_ACCOUNT_ID=$(node -e 'console.log(JSON.parse(process.argv[1]).accountId)' "$me")
say "Conta autenticada: $(node -e 'console.log(JSON.parse(process.argv[1]).displayName)' "$me") (accountId $JIRA_OPERATOR_ACCOUNT_ID)"
write_env JIRA_OPERATOR_ACCOUNT_ID "$JIRA_OPERATOR_ACCOUNT_ID"

# ── 4 ─────────────────────────────────────────────────────────────────────
stage "Jira CON: nome da transição para done"
say "VAN usa 'Itens concluídos' (confirmado em docs/results/007). CON ainda não foi confirmado."
say "Estados 'done' dos tipos de issue de CON, lidos agora do Jira:"
statuses=$(jira_get "/rest/api/3/project/CON/statuses" 2>/dev/null || true)
if [[ -n "$statuses" ]]; then
  node -e '
    const seen = new Set();
    for (const t of JSON.parse(process.argv[1])) for (const s of t.statuses)
      if (s.statusCategory?.key === "done") seen.add(s.name);
    console.log([...seen].map((n) => "    - " + n).join("\n") || "    (nenhum encontrado)");
  ' "$statuses"
else
  warn "não consegui ler os estados de CON (sem permissão?)"
fi
note "O nome da TRANSIÇÃO costuma ser igual ao do estado, mas não é garantido. Confirme em uma issue CON:"
step "Abra uma issue CON, clique no botão de status e veja o nome exato da opção que leva a 'concluído'."
open_url "$JIRA_BASE/browse/CON"
ask_or CON_DONE_TRANSITION "Nome exato da transição done de CON:" "Itens concluídos"
write_env CON_DONE_TRANSITION "$CON_DONE_TRANSITION"
note "O teste de conformidade do adapter (npm run conformance:jira) só cobre VAN; o done de CON é validado no piloto."

# ── 5 ─────────────────────────────────────────────────────────────────────
stage "Perfis Pi (auth do modelo) de cada instância"
say "O container monta o perfil Pi da instância somente leitura; ele precisa de auth.json,"
say "settings.json e da skill implement, e do modelo github-copilot/gpt-6-luna autenticado."
ask_or PROFILE_PESSOAL "Diretório do perfil Pi da instância PESSOAL:" "$HOME/.pi/agent"
ask_or PROFILE_TRABALHO "Diretório do perfil Pi da instância TRABALHO:" "$HOME/.pi-deere/agent"
for pair in "PESSOAL:$PROFILE_PESSOAL" "TRABALHO:${PROFILE_TRABALHO}"; do
  name="${pair%%:*}"; dir="${pair#*:}"
  no_spaces "$dir" || { warn "caminho com espaço não é suportado: $dir"; exit 1; }
  for file in auth.json settings.json skills/implement/SKILL.md; do
    [[ -e "$dir/$file" ]] && say "ok   $name: $file" || { warn "$name: falta $dir/$file"; exit 1; }
  done
  # The triage of PR comments needs this skill in the profile. The operator links it deliberately: the
  # wizard never changes the profile, it only says what is missing.
  if [[ -e "$dir/skills/gh-address-comments/SKILL.md" ]]; then
    say "ok   $name: skills/gh-address-comments/SKILL.md"
  else
    warn "$name: falta a skill gh-address-comments em $dir/skills; sem ela, comentário humano no PR vira pedido de ajuda"
    SKIPPED+=("linkar a skill gh-address-comments em $dir/skills (ex.: ln -s ~/.agents/skills/gh-address-comments $dir/skills/gh-address-comments)")
  fi
  models_out=$(PI_CODING_AGENT_DIR="$dir" pi --list-models gpt-6-luna 2>/dev/null || true)
  if grep -q "gpt-6-luna" <<<"$models_out"; then
    say "ok   $name: modelo gpt-6-luna disponível no perfil"
  else
    warn "$name: não vi gpt-6-luna em 'pi --list-models' com esse perfil; faça login do github-copilot nele (pi /login) antes de seguir"
    SKIPPED+=("confirmar login github-copilot no perfil $name ($dir)")
  fi
done
write_env PROFILE_PESSOAL "$PROFILE_PESSOAL"
write_env PROFILE_TRABALHO "$PROFILE_TRABALHO"

# ── 6 ─────────────────────────────────────────────────────────────────────
stage "Alvos do piloto"
say "Todos os 16 alvos ficam na configuração; só os escolhidos abaixo ficam enabled."
say "A spec da tarefa é a própria issue; o review é feito pelo /implement dentro da invocação."
echo
all_projects | awk -F'|' '{ printf "    %-9s %-18s %s\n", $1, $2, $3 }'
echo
is_project() { all_projects | awk -F'|' -v n="$1" '$2==n {found=1} END {exit !found}'; }
while true; do
  ask_or PILOT_GH_PROJECT "Projeto GitHub Issues do piloto (nome):" "my-software-factory"
  ask_or PILOT_JIRA_PROJECT "Projeto Jira do piloto (nome, ex.: van-playbooks):" ""
  ask_or PILOT_EXTRA_PROJECTS "Outros a habilitar (nomes separados por vírgula, opcional; precisa para o N=2):" ""
  invalid=""
  for name in "$PILOT_GH_PROJECT" "$PILOT_JIRA_PROJECT" ${PILOT_EXTRA_PROJECTS//,/ }; do
    is_project "$name" || invalid="$invalid '${name}'"
  done
  [[ -z "$invalid" ]] && break
  warn "nome(s) inválidos ou ausentes (o projeto Jira é obrigatório):${invalid}"
  [[ -t 0 ]] || exit 1
done
write_env PILOT_GH_PROJECT "$PILOT_GH_PROJECT"
write_env PILOT_JIRA_PROJECT "$PILOT_JIRA_PROJECT"
write_env PILOT_EXTRA_PROJECTS "$PILOT_EXTRA_PROJECTS"
ENABLED=",$PILOT_GH_PROJECT,$PILOT_JIRA_PROJECT,$PILOT_EXTRA_PROJECTS,"

# ── 7 ─────────────────────────────────────────────────────────────────────
stage "Checkouts locais dos alvos habilitados"
say "Cada trabalho clona a partir do seu checkout local (e empurra para o github.com)."
ask_or CHECKOUT_ROOT "Raiz dos checkouts (espera <raiz>/<owner>/<repo>):" "$HOME/dev/github.com"
CHECKOUT_ROOT="${CHECKOUT_ROOT/#\~/$HOME}"
no_spaces "$CHECKOUT_ROOT" || { warn "caminho com espaço não é suportado"; exit 1; }
[[ "$CHECKOUT_ROOT" == /* ]] || { warn "use um caminho absoluto"; exit 1; }
write_env CHECKOUT_ROOT "$CHECKOUT_ROOT"
while IFS='|' read -r -u 3 _instance name repo _adapter account _jirakey; do
  [[ "$ENABLED" == *",$name,"* ]] || continue
  path="$CHECKOUT_ROOT/$repo"
  if [[ ! -d "$path/.git" ]]; then
    warn "falta $path"
    if confirm "Clonar $repo com a conta $account?"; then
      mkdir -p "$(dirname "$path")"; gh_as "$account" repo clone "$repo" "$path"
    else
      SKIPPED+=("checkout de $repo em $path")
      continue
    fi
  fi
  # Over https with the project account's token, so it works whatever the origin's protocol (ssh keys included).
  # Only refs/remotes/origin/main moves; no local branch or working tree is touched.
  if GH_TOKEN=$(gh auth token --user "$account") git -C "$path" \
    -c 'credential.https://github.com.helper=!f() { test "$1" = get && echo username=x-access-token && echo "password=$GH_TOKEN"; }; f' \
    fetch --quiet "https://github.com/$repo.git" "+refs/heads/main:refs/remotes/origin/main" 2>/dev/null; then
    say "ok   $repo (origin/main atualizada)"
  else
    warn "$repo: não consegui atualizar origin/main"
  fi
done 3< <(all_projects)
note "A main LOCAL é a base do clone: se estiver atrás ou adiante da origin, o check do estágio 9 falha/avisa; atualize-a você mesmo (git pull)."

# ── 8 ─────────────────────────────────────────────────────────────────────
stage "Gerar configuração e ajustes locais (.pilot/)"
say "Config: $CONFIG (a partir de $TEMPLATE) e $LOCAL (caminhos desta máquina). Ambos git-ignored."
regenerate=1
if [[ -f "$CONFIG" ]] && ! confirm "$CONFIG já existe; regenerar? (perde edições manuais, como N e enabled)"; then regenerate=0; fi
(( regenerate )) && node -e '
  const fs = require("fs");
  const [template, out, localOut, enabledCsv, operator, conDone, pessoal, trabalho, root, image] = process.argv.slice(1);
  const enabled = new Set(enabledCsv.split(",").filter(Boolean));
  const cfg = JSON.parse(fs.readFileSync(template, "utf8")
    .replaceAll("__JIRA_OPERATOR_ACCOUNT_ID__", operator).replaceAll("__CON_DONE_TRANSITION__", conDone));
  const checkouts = {};
  for (const i of cfg.instances) for (const p of i.projects) {
    p.enabled = enabled.has(p.name);
    checkouts[p.repository] = `${root}/${p.repository}`;
  }
  fs.writeFileSync(out, JSON.stringify(cfg, null, 2) + "\n");
  fs.writeFileSync(localOut, JSON.stringify({
    image, profiles: { pessoal, trabalho }, checkouts,
  }, null, 2) + "\n");
' "$TEMPLATE" "$CONFIG" "$LOCAL" "$ENABLED" "$JIRA_OPERATOR_ACCOUNT_ID" "$CON_DONE_TRANSITION" \
  "$PROFILE_PESSOAL" "$PROFILE_TRABALHO" "$CHECKOUT_ROOT" "$IMAGE"
say "ok   $CONFIG e $LOCAL escritos"
cat > "$PILOT_DIR/run.sh" <<'RUN_EOF'
#!/usr/bin/env bash
# uso: .pilot/run.sh <pessoal|trabalho> [--check|--once]
set -euo pipefail
cd "$(dirname "$0")/.."
instance="${1:?uso: .pilot/run.sh <pessoal|trabalho> [--check|--once]}"; shift || true
# Só as variáveis do Jira são exportadas, lidas como texto (sem eval): o resto do arquivo pode ter espaços.
while IFS='=' read -r key value; do export "$key=$value"; done < <(grep -E '^(JIRA_URL|JIRA_USERNAME|JIRA_API_TOKEN)=' .pilot/pilot.env)
exec npm run --silent run -- --config .pilot/config.json --local .pilot/local.json \
  --instance "$instance" --state-dir "$PWD/.pilot/state/$instance" "$@"
RUN_EOF
chmod +x "$PILOT_DIR/run.sh"
say "ok   $PILOT_DIR/run.sh"
note "Trocar N, polling ou enabled depois: edite $CONFIG (maxConcurrent, pollIntervalSeconds, enabled)."

# ── 9 ─────────────────────────────────────────────────────────────────────
stage "Labels do GitHub e check de prontidão (somente leitura)"
say "Crio as labels (só se não existirem) ready-for-agent e agent-claimed nos repositórios GitHub habilitados."
while IFS='|' read -r -u 3 _instance name repo adapter account _jirakey; do
  [[ "$adapter" == "github" && "$ENABLED" == *",$name,"* ]] || continue
  ensure_label "$account" "$repo" ready-for-agent 0e8a16 "Pronta para o agente"
  ensure_label "$account" "$repo" agent-claimed fbca04 "Reivindicada pela factory"
done 3< <(all_projects)
say "Agora o check: Docker, imagem, perfil, token, tracker (descoberta), operador Jira, e checkouts."
for instance in pessoal trabalho; do
  while true; do
    printf '\n  %s── instância %s ──%s\n' "$BOLD" "$instance" "$RESET"
    if "$PILOT_DIR/run.sh" "$instance" --check; then break; fi
    warn "algo falhou em $instance"
    confirm "Corrigi; rodar o check de novo?" || { SKIPPED+=("check da instância $instance"); break; }
  done
done
pause "Enter para seguir"

# ── 10 ────────────────────────────────────────────────────────────────────
stage "Criar as tarefas reais e autorizá-las (você)"
say "Autorizar = aplicar ready-for-agent. Use tarefas PEQUENAS e seguras; deploy produtivo e merge nunca são da factory."
say "A descrição da issue é a spec que o agente e os reviewers recebem: escreva o que construir, as restrições e como validar."
echo
step "GitHub ($PILOT_GH_PROJECT): crie a issue e aplique a label ready-for-agent."
gh_repo=$(all_projects | awk -F'|' -v n="$PILOT_GH_PROJECT" '$2==n {print $3}')
open_url "https://github.com/$gh_repo/issues/new"
pause "Issue GitHub criada e rotulada? Enter"
step "Jira ($PILOT_JIRA_PROJECT): crie a issue com TODAS estas condições:"
say "    • projeto e label de roteamento do alvo (a label do projeto, uma só);"
say "    • label ready-for-agent;"
say "    • na sprint ATUAL e atribuída a você;"
say "    • sem links de bloqueio (Blocks) e sem a label agent-claimed."
open_url "$JIRA_BASE/browse/$(all_projects | awk -F'|' -v n="$PILOT_JIRA_PROJECT" '$2==n {print $6}')"
pause "Issue Jira criada? Enter"

# ── 11 ────────────────────────────────────────────────────────────────────
stage "Rodada N=1: uma instância por vez"
say "Mantenha N=1 em $CONFIG (maxConcurrent: 1, o padrão do template)."
say "Em um terminal separado, para cada instância:"
printf '\n    %s.pilot/run.sh pessoal%s     # GitHub Issues\n    %s.pilot/run.sh trabalho%s    # Jira\n\n' "$BOLD" "$RESET" "$BOLD" "$RESET"
say "A factory: descobre, faz claim (+doing), roda o /implement no Docker e espera o PR."
say "Acompanhe, em outro terminal:"
printf '    npm run logs -- --help        # logs/estado por instância\n'
printf '    npm run reply   -- --help     # responder a um pedido de ajuda\n'
printf '    npm run pause   -- --help     # pausar novas admissões\n\n'
say "Quando houver PR: revise, espere o CI e FAÇA O MERGE VOCÊ MESMO no github.com."
say "A factory só observa; ao confirmar o merge ela marca done (GitHub: fecha; Jira: transição done)."
say "Comentários 'agent: ...' na issue ou no PR reativam o trabalho (sem o prefixo, são ignorados)."
pause "Quando os dois trabalhos chegarem a done (ou você decidir parar), Enter para registrar as medições"
for run in GH JIRA; do
  printf '\n  %s── medições N=1 · %s ──%s\n' "$BOLD" "$run" "$RESET"
  ask_or "N1_${run}_MINUTOS" "Minutos do claim até done (aprox.):" "?"
  ask_or "N1_${run}_INTERVENCOES" "Quantas intervenções SUAS (respostas, resume, release)?" "0"
  ask_or "N1_${run}_FALHAS" "Falhas/surpresas (curto; ; separa itens):" "nenhuma"
  ask_or "N1_${run}_MUDANCAS" "Mudanças necessárias na factory (curto):" "nenhuma"
  for k in MINUTOS INTERVENCOES FALHAS MUDANCAS; do
    var="N1_${run}_${k}"; write_env "$var" "$(printf '%s' "${!var}" | tr ' ' '_')"
  done
done

# ── 12 ────────────────────────────────────────────────────────────────────
stage "Rodada N=2 e fechamento"
say "N=2 exige duas tarefas em REPOSITÓRIOS diferentes da MESMA instância (um repo só roda uma implementação por vez)."
say "O segundo projeto precisa do checkout local atualizado."
ask_or N2_INSTANCIA "Instância usada no N=2 (pessoal|trabalho):" "trabalho"
ask_or N2_PROJETO "Segundo projeto a habilitar nessa instância (nome da tabela do estágio 6):" ""
is_project "$N2_PROJETO" || { warn "projeto desconhecido: '$N2_PROJETO'"; exit 1; }
write_env N2_INSTANCIA "$N2_INSTANCIA"
write_env N2_PROJETO "$N2_PROJETO"
if confirm "Aplicar em $CONFIG: maxConcurrent=2 em $N2_INSTANCIA e enabled=true em $N2_PROJETO?"; then
  node -e '
    const fs = require("fs");
    const [file, instance, project] = process.argv.slice(1);
    const cfg = JSON.parse(fs.readFileSync(file, "utf8"));
    const inst = cfg.instances.find((i) => i.name === instance);
    const proj = inst?.projects.find((p) => p.name === project);
    if (!proj) { console.error("projeto não pertence a essa instância"); process.exit(1); }
    inst.maxConcurrent = 2; proj.enabled = true;
    fs.writeFileSync(file, JSON.stringify(cfg, null, 2) + "\n");
  ' "$CONFIG" "$N2_INSTANCIA" "$N2_PROJETO" && say "ok   config ajustada para N=2"
fi
say "Rode '.pilot/run.sh $N2_INSTANCIA --check', crie as DUAS issues autorizadas (ready-for-agent) e rode .pilot/run.sh $N2_INSTANCIA."
pause "Enter ao terminar as duas tarefas (merge humano incluído)"
ask_or N2_MINUTOS "Minutos até as duas chegarem a done (aprox.):" "?"
ask_or N2_PARALELOS "Os dois rodaram em paralelo de fato? (sim/nao):" "sim"
ask_or N2_FALHAS "Falhas/surpresas (curto):" "nenhuma"
ask_or N2_CUSTO "Custo/tokens observados (Pi/Copilot; curto):" "?"
ask_or ENVELOPE "Docker, tracker ou composição excederam o envelope acordado? (nao / descreva):" "nao"
for var in N2_MINUTOS N2_PARALELOS N2_FALHAS N2_CUSTO ENVELOPE; do write_env "$var" "$(printf '%s' "${!var}" | tr ' ' '_')"; done
say ""
say "Medições salvas em $ENV_FILE (sem o token Jira no relatório)."
say "Peça ao agente: 'complete docs/results/009-pilot.md com .pilot/pilot.env e os jobs em .pilot/state/*'."
if [[ "$ENVELOPE" != "nao" ]]; then
  warn "Você registrou estouro de envelope: o trade-off volta ao operador ANTES de mudar o MVP (critério da #10)."
fi
# ──────────────────────────────────────────────────────────────────────────

finish
